"use strict";(function(){const e=document.documentElement;window.BREAKPOINTS={up:t=>e.clientWidth>=(BREAKPOINTS[t]||t),down:t=>e.clientWidth<(BREAKPOINTS[t]||t),isMobile:()=>BREAKPOINTS.down("mobile"),isTablet:()=>BREAKPOINTS.up("mobile")&&BREAKPOINTS.down("desktop"),isDesktop:()=>BREAKPOINTS.up("desktop")};const n=getComputedStyle(document.documentElement);["xxs","xs","sm","md","lg","xl","xxl","mobile","desktop","content","wide"].forEach(t=>{const o=n.getPropertyValue(`--width-${t}`);o&&(BREAKPOINTS[t]=parseInt(o))})})();
